import{_ as t,o as a,c as r,a2 as i}from"./chunks/framework.mRCPFc5l.js";const g=JSON.parse('{"title":"Browse Recipes","description":"","frontmatter":{"title":"Browse Recipes"},"headers":[],"relativePath":"docs/getting-started/browse-recipes.md","filePath":"docs/getting-started/browse-recipes.md","lastUpdated":1790394058000}'),o={name:"docs/getting-started/browse-recipes.md"};function s(n,e,p,c,l,d){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="browse-recipes" tabindex="-1">Browse Recipes <a class="header-anchor" href="#browse-recipes" aria-label="Permalink to &quot;Browse Recipes&quot;">​</a></h1><p><strong>Recipes</strong> are pre-built charts and breakdowns over your project&#39;s data — spending by category, account balances over time, portfolio performance, debt payoff progress, and more. Opening one shows results instantly, so they&#39;re the fastest way to check something you&#39;ll want to look at often.</p><h2 id="opening-a-recipe" tabindex="-1">Opening a recipe <a class="header-anchor" href="#opening-a-recipe" aria-label="Permalink to &quot;Opening a recipe&quot;">​</a></h2><p>The Recipes panel sits alongside chat in your project. Pick a recipe from the list to run it and see its chart. A time-period selector (1 month up to 10 years, or a custom range) applies to whichever recipe is open, so you can quickly compare, say, this month&#39;s spending against last year&#39;s.</p><p>One recipe can be <strong>pinned</strong> as a larger summary tile, with a few other pinned recipes shown as smaller tiles beside it — a quick at-a-glance dashboard for the project.</p><p>On a Combined Finance project, a focus switcher lets you flip between views like Combined Spending, Spending, Investing, Net Worth, and Retirement, each offering its own relevant set of recipes.</p><h2 id="drilling-into-detail" tabindex="-1">Drilling into detail <a class="header-anchor" href="#drilling-into-detail" aria-label="Permalink to &quot;Drilling into detail&quot;">​</a></h2><p>Click a bar, category, or KPI on a chart to drill in — the tile swaps to a detailed table or breakdown for just that slice, and you can step back out to the overview. If the underlying data changes while a recipe is open (for example, a new source finishes importing), the result dims to show it&#39;s stale rather than disappearing, so you know to re-run it.</p><h2 id="next-step" tabindex="-1">Next step <a class="header-anchor" href="#next-step" aria-label="Permalink to &quot;Next step&quot;">​</a></h2><p>Recipes are great for questions you&#39;ll ask often. For anything else — or to dig deeper into a specific number — try <a href="/docs/getting-started/ask-questions">asking questions about your data</a> in chat.</p>',10)])])}const u=t(o,[["render",s]]);export{g as __pageData,u as default};
